"""Household records surface; server values are written as text, never markup."""
from __future__ import annotations

import html

CSS = r"""
#thingsLink{display:inline-flex;padding:8px 12px;border:1px solid var(--border,#c7cfd8);border-radius:8px;color:inherit;text-decoration:none;margin:6px}
.mt-page{font:16px/1.5 system-ui,sans-serif;max-width:1060px;margin:0 auto;padding:32px 24px;color:#21332f;background:#f7f8f4;min-height:100vh;box-sizing:border-box}
.mt-page *{box-sizing:border-box}.mt-page h1{font-size:34px;letter-spacing:-1px;margin:0}.mt-page h2{font-size:21px;margin:0 0 12px}.mt-page p{color:#50635c}.mt-bar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:18px 0}
.mt-page button,.mt-page .mt-link{font:inherit;background:#fff;color:#214c40;border:1px solid #a9bdb2;border-radius:9px;padding:9px 14px;cursor:pointer;text-decoration:none}.mt-page button:hover{background:#edf2e9}.mt-page button:focus-visible,.mt-page input:focus-visible,.mt-page textarea:focus-visible{outline:3px solid #b0812b;outline-offset:2px}.mt-page button:disabled{opacity:.5;cursor:wait}.mt-page .mt-primary{background:#275846;color:white}.mt-page .mt-danger{color:#8c302e;border-color:#c68b84}
.mt-grid{display:grid;grid-template-columns:260px minmax(0,1fr);gap:22px}.mt-card{border:1px solid #c9d4c8;border-radius:16px;background:#fff;padding:22px;min-width:0}.mt-list{display:flex;flex-direction:column;gap:8px}.mt-list button{text-align:start}.mt-form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.mt-form label{display:flex;flex-direction:column;font-size:14px;gap:4px}.mt-page input,.mt-page textarea,.mt-page select{font:inherit;border:1px solid #a9bdb2;border-radius:7px;padding:9px;width:100%;background:#fff;color:#21332f}.mt-page textarea{min-height:78px;resize:vertical}.mt-wide{grid-column:1/-1}.mt-page pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;background:#f3f5ef;border-radius:9px;padding:12px}.mt-status{min-height:28px;color:#743c24;overflow-wrap:anywhere}.mt-muted{font-size:14px;color:#60726a}.mt-file{display:flex;gap:10px;flex-wrap:wrap;align-items:center;border-top:1px solid #e1e7de;padding:8px 0}.mt-file input{max-width:300px}.mt-page [hidden]{display:none!important}
@media(max-width:680px){.mt-page{padding:20px 14px}.mt-grid{grid-template-columns:1fr}.mt-form{grid-template-columns:1fr}.mt-card{padding:16px}.mt-page h1{font-size:28px}}
"""

JS = r"""
(function(){'use strict';
const t=k=>window.VOOLT('things.'+k), common=k=>window.VOOLT(k);
const root=document.getElementById('myThingsRoot');
if(!root){const link=document.createElement('a');link.id='thingsLink';link.href='/my-things';link.textContent=t('title');const host=document.getElementById('contactsBtn');if(host)host.after(link);else{const main=document.querySelector('main')||document.body;main.prepend(link);}return;}
let items=[], selected=null, pendingFile=null, busy=false;
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;};
const button=(label,fn,cls)=>{const b=el('button',label,cls);b.type='button';b.onclick=()=>task(fn);return b;};
const status=el('div','','mt-status');status.setAttribute('role','status');status.setAttribute('aria-live','polite');
const list=el('nav','','mt-list');list.setAttribute('aria-label',t('title'));const detail=el('section','','mt-card');
const say=s=>{status.textContent=s||'';};
async function request(action,data){const res=await fetch('/api/my-things'+(action?'/'+action:''),data===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),cache:'no-store'});const body=await res.json();if(!res.ok||!body.ok){const e=new Error(body.error||'failed');e.code=body.error;throw e;}return body;}
async function task(fn){if(busy)return;busy=true;try{await fn();}catch(e){say(t(e.code==='disabled'?'disabled':e.code==='stale'?'stale':'retry'));}finally{busy=false;}}
function download(blob,name){const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function packet(action,data,name){const res=await fetch('/api/my-things/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!res.ok){throw new Error('download');}download(await res.blob(),name);}
async function fileData(file,kind){if(!file||file.size>8*1024*1024||file.size===0)throw new Error('file');const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=16384)raw+=String.fromCharCode(...bytes.subarray(i,i+16384));return {name:file.name,kind:kind,data:btoa(raw)};}
function fileControl(parent,label,kind,fn){const row=el('div','','mt-file');const input=el('input');input.type='file';input.setAttribute('aria-label',label);row.append(input,button(label,async()=>{const file=await fileData(input.files[0],kind);input.value='';await fn(file);}));parent.append(row);}
function refreshList(){list.textContent='';if(!items.length)list.append(el('p',t('empty'),'mt-muted'));items.forEach(item=>{const b=button(item.name,()=>show(item));b.setAttribute('aria-current',selected&&selected.id===item.id?'true':'false');list.append(b);});}
async function refresh(){items=(await request('')).things;refreshList();}
const fields=['name','maker','model','serial','bought_on','bought_from','price','warranty_end','notes','specs','order_items'];
function form(record){detail.textContent='';detail.append(el('h2',t(record?'edit':'add')));const form=el('form','','mt-form'),inputs={};fields.forEach(key=>{const label=el('label',t(key));const input=el(['notes','specs','order_items'].includes(key)?'textarea':'input');input.name=key;input.id='mt-'+key;input.value=record&&record[key]||'';if(key==='bought_on'||key==='warranty_end')input.type='date';if(key==='name')input.required=true;if(input.tagName==='TEXTAREA')label.className='mt-wide';inputs[key]=input;label.append(input);form.append(label);});
const bar=el('div','','mt-bar mt-wide');const save=el('button',common('notif.save'),'mt-primary');save.type='submit';bar.append(save,button(common('dialog.cancel'),()=>{pendingFile=null;record?show(record):welcome();}));form.append(bar);form.onsubmit=e=>{e.preventDefault();task(async()=>{const values={};fields.forEach(key=>values[key]=inputs[key].value);const body={fields:values,confirm:true};if(record&&record.id){body.id=record.id;body.revision=record.revision;}else if(pendingFile)body.file=pendingFile;const res=await request('save',body);pendingFile=null;await refresh();show(res.thing);say(t('saved'));});};detail.append(form);inputs.name.focus();}
function welcome(){selected=null;detail.textContent='';detail.append(el('h2',t('empty')),el('p',t('intro')));refreshList();}
function show(record){selected=record;detail.textContent='';detail.append(el('h2',record.name));fields.filter(key=>key!=='name'&&record[key]).forEach(key=>{const line=el('p');line.append(el('strong',t(key)+': '),document.createTextNode(record[key]));detail.append(line);});const bar=el('div','','mt-bar');bar.append(button(t('edit'),()=>form(record)),button(common('dialog.delete'),()=>confirmDelete(record),'mt-danger'));detail.append(bar);
(record.files||[]).forEach(file=>detail.append(el('p',file.name+' · '+file.kind,'mt-muted')));
const kind=el('select');['receipt','manual','photo','note'].forEach(key=>{const option=el('option',t(key));option.value=key;kind.append(option);});kind.setAttribute('aria-label',t('attach'));detail.append(kind);fileControl(detail,t('attach'),'note',async(file)=>{file.kind=kind.value;const res=await request('attach',{id:record.id,revision:record.revision,file:file});await refresh();show(res.thing);});
const tools=el('div','','mt-bar');tools.append(button(t('warranty'),async()=>renderResult(await request('prepare',{id:record.id,kind:'warranty'}))));detail.append(tools);const issue=el('textarea');issue.setAttribute('aria-label',t('issue'));issue.placeholder=t('issue');detail.append(issue);const requests=el('div','','mt-bar');['return','repair'].forEach(kind=>requests.append(button(t(kind),async()=>renderResult(await request('prepare',{id:record.id,kind:kind,issue:issue.value})))));requests.append(button(t('packet'),async()=>packet('packet',{id:record.id,kind:'repair',issue:issue.value},'request-draft.zip')));detail.append(requests);
const observed=el('textarea');observed.setAttribute('aria-label',t('observed'));observed.placeholder=t('observed');detail.append(observed);const compare=el('div','','mt-bar');compare.append(button(t('fits'),async()=>renderResult(await request('prepare',{id:record.id,kind:'fits',observed:observed.value}))),button(t('delivery'),()=>delivery(record,observed.value)));detail.append(compare);refreshList();}
function renderResult(result){let out=detail.querySelector('#mt-result');if(!out){out=el('section');out.id='mt-result';detail.append(out);}out.textContent='';out.append(el('p',t('draft_only'),'mt-muted'));if(result.draft)out.append(el('pre',result.draft));if(result.warranty)out.append(el('p',t('warranty_'+result.warranty.state)+(result.warranty.end?' · '+result.warranty.end:'')));['matches','conflicts','unknown'].forEach(key=>{if(result[key]&&result[key].length){out.append(el('h3',t(key)));result[key].forEach(value=>out.append(el('p',value)));}});out.scrollIntoView({block:'nearest'});}
async function delivery(record,observed){const result=await request('prepare',{id:record.id,kind:'delivery',observed:observed,arrived:[]});renderResult(result);const out=detail.querySelector('#mt-result'),checks=[];out.append(el('p',t('arrived')));result.expected.forEach(item=>{const label=el('label'),input=el('input');input.type='checkbox';input.style.width='auto';checks.push([item,input]);label.append(input,document.createTextNode(' '+item));out.append(label,el('br'));});out.append(button(t('check_delivery'),async()=>{const checked=checks.filter(pair=>pair[1].checked).map(pair=>pair[0]);renderResult(await request('prepare',{id:record.id,kind:'delivery',observed:observed,arrived:checked}));}));}
function confirmDelete(record){detail.textContent='';detail.append(el('h2',t('delete_question')),el('p',record.name),el('p',t('delete_files')),button(common('dialog.delete'),async()=>{await request('delete',{id:record.id,revision:record.revision,confirm:true});await refresh();welcome();say(t('deleted'));},'mt-danger'),button(common('dialog.cancel'),()=>show(record)));}
const heading=el('header');heading.append(el('h1',t('title')),el('p',t('intro')));const toolbar=el('div','','mt-bar');toolbar.append(button(t('add'),()=>{pendingFile=null;form(null);},'mt-primary'),button(common('header.export'),()=>packet('export',{},'my-things.zip')));const settings=el('label',t('enabled')+' '),toggle=el('input');toggle.type='checkbox';toggle.style.width='auto';toggle.onchange=()=>task(async()=>{const preference=await request('preferences',{enabled:toggle.checked});if(preference.enabled){await refresh();welcome();}else{items=[];selected=null;refreshList();detail.textContent='';say(t('disabled'));}});settings.append(toggle);toolbar.append(settings);root.append(heading,toolbar,status);
const intake=el('section','','mt-card');intake.append(el('h2',t('intake')));fileControl(intake,t('receipt_propose'),'receipt',async file=>{const result=await request('propose',{file:file});if(result.reading.state!=='read'){say(t('unreadable'));return;}pendingFile=file;form(result.fields);const evidence=el('pre',result.evidence.map(e=>e.quote).join('\n'));evidence.id='mt-proposal-evidence';detail.prepend(el('p',t('review')),evidence);});fileControl(intake,t('match_photo'),'photo',async file=>{const result=await request('match',{file:file});detail.textContent='';detail.append(el('h2',t(result.state==='match'?'matched':result.state==='choose'?'choose':result.state==='no_match'?'no_match':'unreadable')));result.candidates.forEach(candidate=>{const card=el('div','','mt-card');card.append(el('h3',candidate.name),el('pre',candidate.evidence.map(e=>e.saved+' ← '+e.quote).join('\n')),button(t('open'),()=>show(items.find(item=>item.id===candidate.id))));detail.append(card);});if(result.state==='no_match')detail.append(button(t('add'),()=>form(null)));});
const grid=el('div','','mt-grid'),aside=el('aside','','mt-card');aside.append(el('h2',t('saved_things')),list);grid.append(aside,detail);root.append(intake,el('div','','mt-bar'),grid);task(async()=>{const pref=await request('preferences');toggle.checked=pref.enabled;if(pref.enabled){await refresh();welcome();}else say(t('disabled'));});
window.VoolMyThings=Object.freeze({refresh:refresh});
})();
"""


def render_my_things_fragment() -> str:
    return '<style>' + CSS + '</style><script>' + JS + '</script>'


def render_my_things_page(locale: str) -> str:
    from core.i18n.catalog import catalog_for
    from core.i18n.page_bundle import render_i18n_bootstrap

    title = html.escape(catalog_for(locale).text('things.title'))
    return ('<!doctype html><html lang="' + html.escape(locale, quote=True) + '"><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width,initial-scale=1"><title>' + title + '</title>'
            + render_i18n_bootstrap(locale) + '</head><body class="mt-page"><main id="myThingsRoot"></main>'
            + render_my_things_fragment() + '</body></html>')
